/// operation caller. No consumer hashing or current-seal retry substitution.
pub fn read_plugin_state_store_contract(
    dir: &Path,
    plugin_id: &str,
) -> Option<(String, op_state_store::PluginSchema)> {
    if plugin_id.is_empty()
        || !plugin_id
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'-' | b'.'))
