/// Summary of one file entry inside an encoded `FileDescriptorSet`, borrowing
/// the underlying descriptor bytes.
#[derive(Debug)]
pub struct FileSummary<'a> {
    pub name: String,
    pub package: String,
    pub messages: Vec<String>,
